(() => {
'use strict';
const BANK=window.QUESTION_BANK, MAP=new Map(BANK.map(q=>[q.id,q]));
const MODULES=[{id:'basics',name:'党章与党员基础',desc:'性质宗旨、誓词、权利义务、入党与转正',time:'先练这一组'},{id:'theory',name:'基本理论框架',desc:'两个确立、中国式现代化、发展理念与精神',time:'建立知识框架'},{id:'discipline',name:'组织生活与纪律',desc:'六大纪律、五种处分、组织设置与生活制度',time:'分清数字与概念'},{id:'current',name:'时事政治',desc:'2026年政府工作报告、十五五与学习教育',time:'记住时间和关键词'},{id:'school',name:'校史校情',desc:'求是书院、西迁并校、校训校歌与大学精神',time:'用短题查缺补漏'}];
const TYPES={single:'单选题',multi:'多选题',fill:'填空题',recite:'简答 · 默写'}, KEY='qiushi-study-v1';
const icons={book:'<path d="M3 4h6a3 3 0 0 1 3 3v14a5 5 0 0 0-5-3H3z"/><path d="M21 4h-6a3 3 0 0 0-3 3v14a5 5 0 0 1 5-3h4z"/>',home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',repeat:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M5 8a7 7 0 0 1 12-3l3 4M4 15l3 4a7 7 0 0 0 12-3"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h.1M3 12h.1M3 19h.1"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s??'').normalize('NFKC').toLowerCase().replace(/[\s，,。；;：:、！!？?（）()“”‘’"']/g,'');
function grade(q,v){if(q.type==='recite')return window.RECALL.grade(q,v);if(q.type==='fill'){const parts=q.blanks.map((b,i)=>b.answers.some(a=>norm(a)===norm(v?.[i])));return {correct:parts.every(Boolean),parts};}const picked=[...new Set(v||[])].sort((a,b)=>a-b),right=[...q.answers].sort((a,b)=>a-b);return {correct:JSON.stringify(picked)===JSON.stringify(right)};}
function shuffle(list){const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function complete(q,v){if(q.type==='recite')return typeof v==='string'&&v.trim().length>0;return q.type==='fill'?q.blanks.every((_,i)=>String(v?.[i]||'').trim()):(v||[]).length>0;}
window.QUIZ_CORE={grade,norm,shuffle,complete};
let storageOK=true, bankUpdated=false, state={records:{},bookmarks:[],session:null,history:[],revision:2};
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&saved.records&&Array.isArray(saved.bookmarks)){state={...state,...saved};
if(saved.revision!==2){
const migrations=window.QUESTION_MIGRATIONS||{};
state.bookmarks=[...new Set(state.bookmarks.map(id=>migrations[id]||id))].filter(id=>MAP.has(id));
for(const [oldId,newId] of Object.entries(migrations)){if(state.records[oldId]?.needsReview&&!state.records[newId])state.records[newId]={attempts:0,streak:0,errors:0,needsReview:true};}
state.revision=2;bankUpdated=true;
}
if(state.session?.ids.some(id=>!MAP.has(id))){state.previousSession=state.session;state.session=null;}
save();}}catch{storageOK=false;}
let view='home',search='',filter='all',lastFocus=null;
const root=document.getElementById('app');
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2800);}
const mastered=id=>(state.records[id]?.streak||0)>=2;
const wrong=id=>!!state.records[id]?.needsReview;
const totalSeen=()=>BANK.filter(q=>state.records[q.id]?.attempts).length;
const masteredCount=()=>BANK.filter(q=>mastered(q.id)).length;
const wrongIds=()=>BANK.filter(q=>wrong(q.id)).map(q=>q.id);
const moduleName=id=>MODULES.find(m=>m.id===id)?.name||'综合练习';
function sourceHTML(q){return q.source.href?`<a class="source" href="${esc(q.source.href)}" target="_blank" rel="noopener noreferrer">依据：${esc(q.source.label)} ↗</a>`:`<span class="source">依据：${esc(q.source.label)}（教材页码为印刷页码）</span>`;}
function answerHTML(q,order){if(q.type==='recite')return `<div class="recite-standard">${esc(q.answer)}</div>`;if(q.type==='fill')return q.blanks.map(b=>`<div>${esc(b.label)}：<strong>${esc(b.answers[0])}</strong></div>`).join('');return q.answers.map(i=>`<div><strong>${String.fromCharCode(65+(order||q.options.map((_,j)=>j)).indexOf(i))}.</strong> ${esc(q.options[i])}</div>`).join('');}
function shell(body){const wc=wrongIds().length;root.innerHTML=`<aside class="sidebar"><button class="brand" data-action="nav" data-view="home" aria-label="求是知新首页"><span class="brand-icon">${icon('book')}</span><span><strong>求是知新</strong><small>发展对象 · 闭卷练习室</small></span></button><nav class="nav" aria-label="主要导航">${[['home','home','学习路径',''],['wrong','repeat','错题重练',wc],['library','list','全部题库',BANK.length],['bookmarks','star','我的收藏',state.bookmarks.length]].map(([id,ic,label,c])=>`<button data-action="nav" data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ic)}${label}${c!==''?`<span class="count">${c}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><strong>慢一点回忆，记得更牢。</strong><div class="mini"><span style="width:${masteredCount()/BANK.length*100}%"></span></div>已巩固 ${masteredCount()} / ${BANK.length} 题<br>连续两轮答对，记为已巩固。<br><button data-action="nav" data-view="about">资料与判分说明</button></div></aside><main id="main" class="main" tabindex="-1"><div class="topline"><span>个人复习 / ${view==='quiz'?'正在练习':view==='result'?'本轮回顾':'发展对象笔试'}</span><span class="save-status"><i class="status-dot"></i>${storageOK?'进度自动保存在当前浏览器':'保存不可用，请保持页面打开'}</span></div>${body}</main>`;}
function render(){if(view==='quiz'&&state.session&&!state.session.finished)quiz();else if(view==='result'&&state.session)result();else if(['library','wrong','bookmarks'].includes(view))library();else if(view==='about')about();else{view='home';home();}}
function navigate(v){view=v;render();window.scrollTo({top:0});}
function home(){const s=state.session;const seen=totalSeen(),master=masteredCount();shell(`<div class="hero"><div><h1>把知识记牢，<br>从这一题开始。</h1><p>先完整默写，再用选择与填空查缺补漏。<br class="desktop-br">先回忆，再校验，<br class="desktop-br">让每一道错题成为下一次的得分点。</p></div><div class="hero-mark">${icon('book')}</div></div>${bankUpdated?'<p class="help-note">题库已升级为整段默写。旧轮次已存档，未改题目的进度与收藏已保留；改版题需要重新练习。</p>':''}${s&&!s.finished?`<div class="resume"><div><strong>上次练到这里</strong><p>${esc(s.title)}，第 ${s.index+1} / ${s.ids.length} 题</p></div><button class="btn primary" data-action="resume">继续练习</button></div>`:''}<div class="stats"><div class="stat"><strong>${seen}</strong><small>/ ${BANK.length}</small><p>已练题目</p></div><div class="stat"><strong>${master}</strong><small>题</small><p>连续两轮答对</p></div><div class="stat"><strong>${wrongIds().length}</strong><small>题</small><p>待复习错题</p></div></div><div class="layout"><section><div class="section-head"><h2>你的复习路径</h2><small>按顺序练，随时可以回头</small></div><div class="path">${MODULES.map((m,i)=>{const qs=BANK.filter(q=>q.module===m.id),done=qs.filter(q=>mastered(q.id)).length;return `<div class="path-row"><span class="step">0${i+1}</span><div class="path-content"><h3>${m.name}</h3><p>${m.desc}</p><p>${qs.length} 题 · 已巩固 ${done} 题</p><div class="mini"><span style="width:${done/qs.length*100}%"></span></div></div><button class="start" data-action="module" data-module="${m.id}" aria-label="练习${m.name}">开始练习</button></div>`;}).join('')}</div><p class="quiet">由你提供的重点表与2026年3月版辅导教材整理，补充已核对的校史、时政资料。用于记忆训练，题型与分值不等同于正式考试。</p></section><aside class="study-tools"><div class="panel"><h3>换一种方式检验</h3><p>打乱顺序后，还能准确记起来吗？</p><label class="control">练习方式<select id="mode"><option value="train">逐题练习 · 立即校验</option><option value="exam">闭卷自测 · 交卷后校验</option></select></label><label class="control">题目类型<select id="type"><option value="all">默写 + 选择 + 填空</option><option value="recite">只练默写</option><option value="fill">只练填空</option><option value="single">只练单选</option><option value="multi">只练多选</option></select></label><label class="control">本轮题量<select id="size"><option value="20">20 题 · 小步练习</option><option value="40">40 题 · 综合自测</option><option value="all">全部题目</option></select></label><label class="control">内容范围<select id="level"><option value="必背">优先必背题</option><option value="all">包含补充题</option></select></label><button class="btn primary wide" data-action="mixed">随机开始 ${icon('arrow')}</button></div><div class="tip"><h3>${icon('spark')} 推荐练法</h3><p>第一轮按路径熟悉知识，第二轮重做错题，第三轮用“只练默写”检验完整记忆。看到答案的题会加入待复习。</p><button class="text-btn" data-action="nav" data-view="about">查看判分与资料说明</button></div></aside></div>`);}
function start(ids,title,mode='train',random=false){if(!ids.length)return toast('当前范围没有可练题目。');const launch=()=>{const ordered=random?shuffle(ids):ids;state.session={ids:ordered,title,mode,index:0,drafts:{},results:{},orders:{},started:Date.now(),finished:false};for(const id of ordered){const q=MAP.get(id);if(q.options)state.session.orders[id]=shuffle(q.options.map((_,i)=>i));}save();navigate('quiz');};if(state.session&&!state.session.finished){dialog('开始新的一轮？','未完成的本轮答题将被替换。已记录的错题、收藏和巩固进度会保留。','开始新一轮',launch);}else launch();}
function record(q,correct,peek){let r=state.records[q.id]||{attempts:0,streak:0,errors:0};r.attempts++;r.lastCorrect=correct&&!peek;r.lastAt=Date.now();if(correct&&!peek){r.streak++;if(r.streak>=2)r.needsReview=false;}else{r.streak=0;r.errors++;r.needsReview=true;}state.records[q.id]=r;}
function check(peek=false){const s=state.session,q=MAP.get(s.ids[s.index]);if(s.results[q.id])return;if(!peek&&!complete(q,s.drafts[q.id]))return toast(q.type==='recite'?'先写出你的答案，再校验。':q.type==='fill'?'先填完每个空，再校验。':'请先选择答案。');const g=grade(q,s.drafts[q.id]);s.results[q.id]={...g,correct:peek?false:g.correct,peek};record(q,g.correct,peek);save();render();document.querySelector('.feedback')?.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function reciteReview(q,r){
if(q.type!=='recite'||r.peek)return '';
const parts=r.parts||[],missing=q.segments.filter((_,i)=>!parts[i]);
return `<div class="recite-review"><p><strong>分句核对：匹配 ${parts.filter(Boolean).length} / ${q.segments.length} 处</strong></p>${r.correct?'<p>完整表述已通过校验。</p>':missing.length?`<p>以下分句未完整匹配，请核对漏字、错字：</p><ul>${missing.map(text=>`<li><span class="review-label">待核对</span>${esc(text)}</li>`).join('')}</ul>`:'<p>要点已覆盖，但连接词、顺序或额外文字仍与标准答案有差异，请逐句对照。</p>'}</div>`;
}
function feedback(q,r,order){return `<section class="feedback ${r.peek?'peek':r.correct?'':'wrong'}" aria-live="polite"><h3>${r.peek?'先记住，再试一次':r.correct?'答对了，继续保持':'还差一点，看看这里'}</h3><div class="answer">${answerHTML(q,order)}</div>${reciteReview(q,r)}<p class="explanation">${esc(q.explanation)}</p>${sourceHTML(q)}${r.peek?'<p class="q-help">本题已加入待复习，查看答案不计为答对。</p>':''}</section>`;}
function quiz(){const s=state.session,q=MAP.get(s.ids[s.index]),v=s.drafts[q.id]||(q.type==='recite'?'':[]),r=s.results[q.id],order=s.orders[q.id],locked=!!r;const completed=s.ids.filter(id=>complete(MAP.get(id),s.drafts[id])).length,checked=Object.keys(s.results).length;
shell(`<div class="backline"><button class="text-btn" data-action="nav" data-view="home">${icon('back')} 返回学习路径</button></div><div class="session-head"><div><h1>${esc(s.title)}</h1><p class="q-help">${s.mode==='exam'?'闭卷自测 · 交卷后统一显示答案':'逐题练习 · 校验后显示答案与解析'}</p></div><button class="btn" data-action="finish">${s.mode==='exam'?'交卷并评分':'结束本轮'}</button></div><div class="q-layout"><section class="question-card"><div class="q-meta"><span class="badge">${TYPES[q.type]}</span>${q.level==='补充'?'<span class="badge extra">补充</span>':''}<span>${moduleName(q.module)}</span><span>${s.index+1} / ${s.ids.length}</span><button class="bookmark ${state.bookmarks.includes(q.id)?'on':''}" data-action="bookmark" data-id="${q.id}" aria-label="${state.bookmarks.includes(q.id)?'取消收藏':'收藏此题'}" aria-pressed="${state.bookmarks.includes(q.id)}">${icon('star')}</button></div><h2 class="question-title">${esc(q.prompt)}</h2><p class="q-help">${q.type==='recite'?(q.mode==='list'?'独立写全各项内容；可换行列举，项目顺序不限，无需复述题目。':'按原文完整默写；标点、空格和换行不影响校验，不要求填写“答：”。'):q.type==='fill'?'填写关键词；空格和常见中文标点不影响判分。':q.type==='multi'?'选择所有正确选项；多选、漏选均计为未答对。':'选择一个最符合题意的选项。'}</p>${q.type==='recite'?`<div class="recite-input"><label for="recitation">你的默写</label><textarea id="recitation" data-recite rows="8" maxlength="3000" autocomplete="off" spellcheck="false" aria-describedby="recite-help" ${locked?'readonly':''} placeholder="从头回忆，在这里写下完整答案……">${esc(v)}</textarea><div class="recite-input-footer"><span id="recite-help">${s.mode==='train'?'Enter 换行 · Ctrl / ⌘ + Enter 校验':'Enter 换行 · 交卷后显示标准答案'}</span><span id="recite-count">${[...v].length} 字</span></div></div>`:q.type==='fill'?`<div class="fills ${q.blanks.length===1?'single':''}">${q.blanks.map((b,i)=>`<div class="fill"><label for="blank-${i}">${esc(b.label)}</label><input id="blank-${i}" data-blank="${i}" type="text" autocomplete="off" spellcheck="false" value="${esc(v[i]||'')}" ${locked?'disabled':''} class="${locked&&!r.peek?(r.parts[i]?'good':'bad'):''}" placeholder="在这里回忆答案">${locked&&!r.peek&&!r.parts[i]?'<small>此空需要再记一遍</small>':''}</div>`).join('')}</div>`:`<fieldset class="options" aria-label="答案选项">${order.map((idx,i)=>{const selected=v.includes(idx),correct=locked&&q.answers.includes(idx),bad=locked&&selected&&!correct;return `<label class="option ${selected?'selected':''} ${locked?'locked':''} ${correct?'correct':''} ${bad?'incorrect':''}"><input type="${q.type==='multi'?'checkbox':'radio'}" name="answer" data-option="${idx}" ${selected?'checked':''} ${locked?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(q.options[idx])}</span>${correct?'<span class="mark">正确</span>':bad?'<span class="mark">误选</span>':''}</label>`;}).join('')}</fieldset>`}${r?feedback(q,r,order):''}<div class="q-actions"><button class="btn" data-action="prev" ${s.index===0?'disabled':''}>上一题</button><div class="actions-right">${s.mode==='train'&&!r?'<button class="text-btn" data-action="peek">先看答案</button><button class="btn primary" data-action="check">校验答案</button>':`<button class="btn primary" data-action="next">${s.index===s.ids.length-1?'完成本轮':'下一题'} ${icon('arrow')}</button>`}</div></div>${s.mode==='train'&&!r?'<button class="text-btn" data-action="next">暂时跳过</button>':''}</section><aside class="q-side"><div class="panel"><h3>本轮答题卡</h3><p>${s.mode==='exam'?`已填写 ${completed}`:`已校验 ${checked}`} / ${s.ids.length} 题</p><div class="q-progress"><span style="width:${(s.mode==='exam'?completed:checked)/s.ids.length*100}%"></span></div><div class="question-grid">${s.ids.map((id,i)=>{const rr=s.results[id],done=complete(MAP.get(id),s.drafts[id]);return `<button data-action="jump" data-index="${i}" class="${i===s.index?'current':''} ${rr?(rr.correct?'good':'bad'):done?'answered':''}" aria-label="第${i+1}题，${rr?(rr.correct?'已答对':'待复习'):done?'已填写':'未答'}" ${i===s.index?'aria-current="step"':''}>${i+1}${rr?(rr.correct?' ✓':' ·'):''}</button>`;}).join('')}</div><div class="legend"><span><i></i>未答</span><span><i class="blue"></i>已填</span>${s.mode==='train'?'<span><i class="green"></i>答对</span><span><i class="red"></i>复习</span>':''}</div></div><div class="tip"><h3>先在脑中找答案</h3><p>${s.mode==='exam'?'本轮所有题目等权计分，折算为100分。可以通过答题卡返回修改；交卷后锁定答案。':'每题本轮仅记一次成绩。连续两轮独立答对后标记已巩固；跳过的题可以从答题卡返回。'}</p></div></aside></div>`);}
function finish(){const s=state.session;if(s.finished)return navigate('result');const untouched=s.ids.filter(id=>!s.results[id]&&!complete(MAP.get(id),s.drafts[id]));const doFinish=()=>{for(const id of s.ids){if(s.results[id])continue;const q=MAP.get(id),g=grade(q,s.drafts[id]);s.results[id]={...g,unanswered:!complete(q,s.drafts[id])};record(q,g.correct,false);}s.finished=true;s.ended=Date.now();state.history.unshift({title:s.title,correct:Object.values(s.results).filter(r=>r.correct).length,total:s.ids.length,at:s.ended});state.history=state.history.slice(0,15);save();navigate('result');};if(untouched.length)dialog('还有题目未完成',`还有 ${untouched.length} 题未填写完整。现在结束将按未答对计入本轮成绩，并加入错题。`,'结束并查看结果',doFinish);else doFinish();}
function result(){const s=state.session;if(!s.finished)return navigate('quiz');const yes=s.ids.filter(id=>s.results[id].correct).length,miss=s.ids.filter(id=>!s.results[id].correct),score=Math.round(yes/s.ids.length*1000)/10;shell(`<div class="result"><button class="text-btn" data-action="nav" data-view="home">${icon('back')} 回到学习路径</button><div class="result-top"><div class="score"><strong>${score}</strong><small>本轮 / 100分</small></div><div><h1>${miss.length?'知道薄弱点，就有了方向。':'这一轮，全部答对！'}</h1><p>${esc(s.title)}<br>答对 ${yes} / ${s.ids.length} 题 · ${miss.length} 题需要复习<br>本轮等权计分，查看答案与未作答计为未答对。</p></div></div><div class="result-actions"><button class="btn primary" data-action="retry" ${miss.length?'':'disabled'}>重练本轮错题 ${miss.length?`(${miss.length})`:''}</button><button class="btn" data-action="again">再来一轮</button><button class="btn" data-action="nav" data-view="home">继续学习路径</button></div><div class="panel"><h3>各模块表现</h3>${MODULES.map(m=>{const ids=s.ids.filter(id=>MAP.get(id).module===m.id);return ids.length?`<div class="result-row"><span>${m.name}</span><strong>${ids.filter(id=>s.results[id].correct).length} / ${ids.length} 题答对</strong></div>`:'';}).join('')}</div><div class="section-head" style="margin-top:30px"><h2>逐题核对</h2><small>展开查看你的答案与解析</small></div>${s.ids.map((id,i)=>{const q=MAP.get(id),r=s.results[id],v=s.drafts[id]||(q.type==='recite'?'':[]);const mine=q.type==='recite'?(v||'未填写'):q.type==='fill'?q.blanks.map((b,j)=>`${b.label}：${v[j]||'未填写'}`).join('；'):v.map(j=>q.options[j]).join('；')||'未选择';return `<article class="library-item"><div class="library-meta"><span class="badge ${r.correct?'':'extra'}">${r.correct?'答对':r.peek?'已看答案':r.unanswered?'未答完整':'待复习'}</span>${i+1} / ${s.ids.length} · ${TYPES[q.type]}</div><h3>${esc(q.prompt)}</h3><details ${r.correct?'':'open'}><summary>查看答案与解析</summary><p class="q-help">你的答案：${esc(mine)}</p><div class="answer">${answerHTML(q,s.orders[id])}</div>${reciteReview(q,r)}<p class="explanation">${esc(q.explanation)}</p>${sourceHTML(q)}</details></article>`;}).join('')}</div>`);}
function library(){const kind=view;let pool=BANK.filter(q=>kind==='wrong'?wrong(q.id):kind==='bookmarks'?state.bookmarks.includes(q.id):true);const base=pool.map(q=>q.id);if(filter!=='all')pool=pool.filter(q=>q.module===filter);if(search)pool=pool.filter(q=>(q.prompt+' '+q.explanation).includes(search));const title={library:'全部题库',wrong:'把错题，再记牢一次。',bookmarks:'值得再看一遍的题'}[kind];shell(`<div class="hero"><div><h1>${title}</h1><p>${kind==='wrong'?'答错、未答完整或看过答案的题会留在这里。连续两轮答对后自动移出。':kind==='bookmarks'?'收藏你容易混淆的题，考前集中回忆。':`共 ${BANK.length} 题，包括完整默写、选择与短填空。可以查阅答案，也可以重新开始练习。`}</p></div></div>${base.length?`<button class="btn primary" data-action="practice-list" data-kind="${kind}">${kind==='wrong'?'重练全部错题':kind==='bookmarks'?'练习收藏题':'随机练习全部题'} ${icon('arrow')}</button>`:''}<div class="library-head"><input id="search" type="search" aria-label="搜索题目或知识点" placeholder="搜索题目或知识点" value="${esc(search)}"><select id="library-filter" aria-label="按模块筛选"><option value="all">全部模块</option>${MODULES.map(m=>`<option value="${m.id}" ${filter===m.id?'selected':''}>${m.name}</option>`).join('')}</select><span class="q-help">${pool.length} 题</span></div><div id="library-items">${pool.length?pool.map(q=>`<article class="library-item"><div class="library-meta"><span class="badge">${TYPES[q.type]}</span>${moduleName(q.module)}<span>${q.level}</span><button class="bookmark ${state.bookmarks.includes(q.id)?'on':''}" data-action="bookmark" data-id="${q.id}" aria-label="${state.bookmarks.includes(q.id)?'取消收藏':'收藏此题'}" aria-pressed="${state.bookmarks.includes(q.id)}">${icon('star')}</button></div><h3>${esc(q.prompt)}</h3>${q.options?`<p class="q-help">${q.options.map((v,i)=>`${String.fromCharCode(65+i)}. ${esc(v)}`).join('<br>')}</p>`:''}<details><summary>展开标准答案与解析</summary><div class="answer">${answerHTML(q)}</div><p class="explanation">${esc(q.explanation)}</p>${sourceHTML(q)}</details></article>`).join(''):`<div class="empty">${icon('book')}<h2>${search||filter!=='all'?'没有找到匹配题目':kind==='wrong'?'还没有待复习错题':kind==='bookmarks'?'把易混题收藏到这里':'暂无题目'}</h2><p>${kind==='wrong'?'完成练习后，错题会自动整理在这里。':'可以先从学习路径开始，答题时点击星形按钮收藏。'}</p><button class="btn" data-action="nav" data-view="home">前往学习路径</button></div>`}</div>`);}
function about(){shell(`<div class="hero"><div><h1>练习与资料说明</h1><p>先准确回忆，再核对标准表述。</p></div></div><div class="panel"><h3>判分规则</h3><p>默写题按标准表述校验，忽略标点、空格、换行和分条编号；标注“项目顺序不限”的题须写全各项，不能添加错误内容。整段原文须保持原有语序。分句匹配用于定位遗漏，不代表正式简答题评分。单选只有一个正确选项；多选须选全且无错选；填空所有空正确才记为答对。填空会忽略空格、全半角差异和常见中文标点，并接受题库中明确列出的常用数字写法。关键文字或未收录的同义表述可能判错，请以展示的标准答案核对。</p><p style="margin-top:16px">每题每轮只记录一次。连续两轮独立答对视为已巩固；看答案、答错或未答完整均会进入待复习。综合自测所有题目等权折算为100分，这是练习分数，不代表正式考试的评分办法。</p><h3 style="margin-top:25px">题目依据</h3><p>以《入党发展对象笔试重点》和2026年3月版《浙江大学党校学生发展对象培训班辅导教材》为基础；每题附来源。教材页码指页面下方印刷页码，PDF阅读器页序通常再加2。校情与近期时政按2026年10月29日核对的信息整理。近期补充题单独标识，不代表确定的考试范围。</p><h3 style="margin-top:25px">进度保存</h3><p>错题、收藏、巩固进度和未完成的一轮保存在当前浏览器。刷新后可从首页继续。不同设备、浏览器及离线版之间不自动同步；清除浏览器数据会清除进度。</p><div class="help-note">真正的笔试还包含简答与论述。本练习室依照你的要求，集中训练固定知识的完整默写、选择与短填空。</div><button class="btn danger" data-action="reset">清空当前浏览器的练习记录</button></div>`);}
function dialog(title,message,label,action){lastFocus=document.activeElement;const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title" aria-describedby="dialog-message"><h2 id="dialog-title">${esc(title)}</h2><p id="dialog-message">${esc(message)}</p><div class="modal-actions"><button class="btn" id="cancel">继续当前练习</button><button class="btn primary" id="confirm">${esc(label)}</button></div></section>`;document.body.append(wrap);const close=()=>{wrap.remove();lastFocus?.focus();};wrap.querySelector('#cancel').onclick=close;wrap.querySelector('#confirm').onclick=()=>{close();action();};wrap.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const bs=[...wrap.querySelectorAll('button')];if(e.shiftKey&&document.activeElement===bs[0]){e.preventDefault();bs[1].focus();}else if(!e.shiftKey&&document.activeElement===bs[1]){e.preventDefault();bs[0].focus();}}});wrap.querySelector('#cancel').focus();}
function updateAnswerCard(){
const s=state.session;if(!s||view!=='quiz')return;
const count=s.mode==='exam'?s.ids.filter(id=>complete(MAP.get(id),s.drafts[id])).length:Object.keys(s.results).length;
const caption=document.querySelector('.q-side .panel > p');if(caption)caption.textContent=`${s.mode==='exam'?'已填写':'已校验'} ${count} / ${s.ids.length} 题`;
const bar=document.querySelector('.q-progress span');if(bar)bar.style.width=`${count/s.ids.length*100}%`;
const button=document.querySelector(`.question-grid [data-index="${s.index}"]`),id=s.ids[s.index],done=complete(MAP.get(id),s.drafts[id]);
if(button&&!s.results[id]){button.classList.toggle('answered',done);button.setAttribute('aria-label',`第${s.index+1}题，${done?'已填写':'未答'}`);}
}
root.addEventListener('input',e=>{if(e.target.dataset.recite!==undefined){const s=state.session,id=s.ids[s.index];if(s.results[id])return;s.drafts[id]=e.target.value;save();updateAnswerCard();const counter=document.getElementById('recite-count');if(counter)counter.textContent=`${[...e.target.value].length} 字`;}if(e.target.dataset.blank!==undefined){const s=state.session,id=s.ids[s.index];if(s.results[id])return;const a=s.drafts[id]||[];a[Number(e.target.dataset.blank)]=e.target.value;s.drafts[id]=a;save();updateAnswerCard();}if(e.target.id==='search'){search=e.target.value;const pos=e.target.selectionStart;render();const input=document.getElementById('search');input.focus();try{input.setSelectionRange(pos,pos);}catch{}}});
root.addEventListener('change',e=>{if(e.target.dataset.option!==undefined){const s=state.session,id=s.ids[s.index],q=MAP.get(id);if(s.results[id])return;const n=Number(e.target.dataset.option);let a=s.drafts[id]||[];s.drafts[id]=q.type==='single'?[n]:e.target.checked?[...a.filter(x=>x!==n),n]:a.filter(x=>x!==n);save();updateAnswerCard();const label=e.target.closest('.option');if(q.type==='single')document.querySelectorAll('.option').forEach(x=>x.classList.remove('selected'));label.classList.toggle('selected',e.target.checked);}if(e.target.id==='library-filter'){filter=e.target.value;render();}});
root.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,s=state.session;if(a==='nav'){search='';filter='all';navigate(b.dataset.view);}else if(a==='module')start(BANK.filter(q=>q.module===b.dataset.module).map(q=>q.id),moduleName(b.dataset.module));else if(a==='mixed'){const t=document.getElementById('type').value,l=document.getElementById('level').value,n=document.getElementById('size').value,mode=document.getElementById('mode').value;let ids=shuffle(BANK.filter(q=>(t==='all'||q.type===t)&&(l==='all'||q.level===l)).map(q=>q.id));if(n!=='all')ids=ids.slice(0,Number(n));start(ids,mode==='exam'?'综合闭卷自测':'随机记忆练习',mode);}else if(a==='resume')navigate('quiz');else if(a==='check')check();else if(a==='peek')check(true);else if(a==='prev'||a==='next'||a==='jump'){if(a==='next'&&s.index===s.ids.length-1)return finish();s.index=a==='jump'?Number(b.dataset.index):s.index+(a==='prev'?-1:1);save();render();document.querySelector('.question-card')?.scrollIntoView({block:'start'});}else if(a==='finish')finish();else if(a==='bookmark'){const id=b.dataset.id;state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();b.classList.toggle('on',state.bookmarks.includes(id));b.setAttribute('aria-pressed',state.bookmarks.includes(id));b.setAttribute('aria-label',state.bookmarks.includes(id)?'取消收藏':'收藏此题');const badge=document.querySelector('.nav [data-view="bookmarks"] .count');if(badge)badge.textContent=state.bookmarks.length;toast(state.bookmarks.includes(id)?'已加入收藏':'已取消收藏');if(view==='bookmarks')render();}else if(a==='retry')start(s.ids.filter(id=>!s.results[id].correct),'本轮错题重练','train',true);else if(a==='again')start([...s.ids],s.title,s.mode,true);else if(a==='practice-list'){const kind=b.dataset.kind;start(BANK.filter(q=>kind==='wrong'?wrong(q.id):kind==='bookmarks'?state.bookmarks.includes(q.id):true).map(q=>q.id),kind==='wrong'?'错题重练':kind==='bookmarks'?'收藏题练习':'全部题目练习','train',true);}else if(a==='reset')dialog('清空所有练习记录？','本浏览器的错题、收藏、巩固进度和未完成练习将被清空，无法撤销。题库会保留。','确认清空',()=>{state={records:{},bookmarks:[],session:null,history:[],revision:2};bankUpdated=false;save();navigate('home');toast('练习记录已清空');});});
root.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.isComposing&&e.target.matches('[data-recite]')&&(e.ctrlKey||e.metaKey)&&state.session.mode==='train'){e.preventDefault();check();return;}if(e.key==='Enter'&&!e.isComposing&&e.target.matches('[data-blank]')&&state.session.mode==='train'){const inputs=[...root.querySelectorAll('[data-blank]')],i=inputs.indexOf(e.target);e.preventDefault();if(i<inputs.length-1)inputs[i+1].focus();else check();}});
render();
})();
